def grade_slot(sorted_scores, score):
    """返回插入 score 后仍保持升序的最右侧位置（同分排最后）。"""
    lo, hi = 0, len(sorted_scores)
    while lo < hi:
        mid = (lo + hi) // 2
        if sorted_scores[mid] < score:
            lo = mid + 1
        else:
            hi = mid
    return lo

